#include <bits/stdc++.h>
using namespace std;
#define int long long
int val(int mid,vector<int> &pfx,int n,int m){
    if(mid<0) return -1;
    int ans=pfx[mid]*6;
    
    for(int i=0; i<=n-mid; i++){
        int p=pfx[mid]*6;
        int p2=pfx[mid+2*i]-pfx[mid];
        p2*=4;
        int p3=pfx[mid+2*i+(n-(mid+i))*3]-pfx[mid+2*i];
        p3*=3;
        ans=max(ans,p+p2+p3);
    }
    return ans;
}
void solve(){
    int n;
    cin>>n;
    int m=3*n;
    vector<int> v(3*n);
    for(int i=0 ; i<m ; i++){
        cin>>v[i];
    }
    sort(v.rbegin(),v.rend());
    vector<int> pfx(m+1,0);
    for(int i=1; i<=m ; i++){
        pfx[i]=pfx[i-1]+v[i-1];
    }
    int ans=0;
    if(n<=5000){for(int i=0 ; i<=n ; i++){
        for(int j=0 ; j<=n-i; j++){
            ans=max(ans,pfx[i]*6+4*(pfx[i+2*j]-pfx[i])+3*(pfx[i+2*j+3*(n-i-j)]-pfx[i+2*j]));
        }
    }
        cout<<ans<<endl;
        return;
    }
    
    // // for(auto it:pfx){
    // //     cout<<it<<" ";
    // // }
    // // cout<<endl;
    int lo=0,hi=n;
    while(hi>=lo){
        int mid=(hi+lo)/2;
        if(val(mid,pfx,n,m)>=val(mid-1,pfx,n,m)){
            ans=val(mid,pfx,n,m);
            lo=mid+1;
        }else{
            hi=mid-1;
        }
    }
    cout<<ans<<endl;
}

signed main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        solve();
    }
}
